/**
 * ChatInterface 组件单元测试
 */

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { ChatInterface } from '../../pages/workflow/components/ChatInterface';

describe('ChatInterface 组件', () => {
  const mockOnSend = jest.fn();
  const mockOnDone = jest.fn();

  const createMockMessage = (overrides = {}) => ({
    role: 'user' as const,
    content: '测试消息内容',
    timestamp: Date.now(),
    ...overrides,
  });

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('应该正确渲染聊天界面', () => {
    const history = [
      createMockMessage({ role: 'user', content: '你好' }),
      createMockMessage({ role: 'assistant', content: '你好！有什么可以帮助你的？' }),
    ];

    render(
      <ChatInterface
        history={history}
        onSend={mockOnSend}
        loading={false}
      />
    );

    // 验证消息显示
    expect(screen.getByText('你好')).toBeInTheDocument();
    expect(screen.getByText('你好！有什么可以帮助你的？')).toBeInTheDocument();
  });

  it('应该显示选中的角度', () => {
    const history = [createMockMessage({ role: 'user', content: '测试' })];
    const selectedAngle = '测试角度标题';

    render(
      <ChatInterface
        history={history}
        selectedAngle={selectedAngle}
        onSend={mockOnSend}
        loading={false}
      />
    );

    // 验证角度标题显示
    expect(screen.getByText(`当前探讨切入点：`)).toBeInTheDocument();
    expect(screen.getByText(selectedAngle)).toBeInTheDocument();
  });

  it('应该允许输入和发送消息', async () => {
    const history: ReturnType<typeof createMockMessage>[] = [];
    mockOnSend.mockResolvedValue(undefined);

    render(
      <ChatInterface
        history={history}
        onSend={mockOnSend}
        loading={false}
      />
    );

    // 输入消息
    const input = screen.getByPlaceholderText('输入你的想法...');
    fireEvent.change(input, { target: { value: '新消息' } });

    // 点击发送按钮
    const sendButton = screen.getByText('发送');
    fireEvent.click(sendButton);

    // 验证 onSend 被调用
    await waitFor(() => {
      expect(mockOnSend).toHaveBeenCalledWith('新消息');
    });
  });

  it('应该在 loading 时禁用发送按钮', () => {
    const history: ReturnType<typeof createMockMessage>[] = [];

    render(
      <ChatInterface
        history={history}
        onSend={mockOnSend}
        loading={true}
      />
    );

    // 验证发送按钮被禁用
    const sendButton = screen.getByText('发送');
    expect(sendButton).toBeDisabled();
  });

  it('应该过滤掉系统消息', () => {
    const history = [
      createMockMessage({ role: 'system', content: '系统消息' }),
      createMockMessage({ role: 'user', content: '用户消息' }),
      createMockMessage({ role: 'assistant', content: '助手消息' }),
    ];

    render(
      <ChatInterface
        history={history}
        onSend={mockOnSend}
        loading={false}
      />
    );

    // 验证系统消息不显示
    expect(screen.queryByText('系统消息')).not.toBeInTheDocument();
    // 验证用户和助手消息显示
    expect(screen.getByText('用户消息')).toBeInTheDocument();
    expect(screen.getByText('助手消息')).toBeInTheDocument();
  });

  it('应该区分用户和助手消息样式', () => {
    const history = [
      createMockMessage({ role: 'user', content: '用户问题' }),
      createMockMessage({ role: 'assistant', content: '助手回答' }),
    ];

    render(
      <ChatInterface
        history={history}
        onSend={mockOnSend}
        loading={false}
      />
    );

    // 验证消息存在
    const userMessage = screen.getByText('用户问题');
    const assistantMessage = screen.getByText('助手回答');

    expect(userMessage).toBeInTheDocument();
    expect(assistantMessage).toBeInTheDocument();
  });

  it('应该在空输入时不发送消息', async () => {
    const history: ReturnType<typeof createMockMessage>[] = [];

    render(
      <ChatInterface
        history={history}
        onSend={mockOnSend}
        loading={false}
      />
    );

    // 不输入内容直接点击发送
    const sendButton = screen.getByText('发送');
    fireEvent.click(sendButton);

    // 验证 onSend 没有被调用
    expect(mockOnSend).not.toHaveBeenCalled();
  });

  it('应该在发送后清空输入框', async () => {
    const history: ReturnType<typeof createMockMessage>[] = [];
    mockOnSend.mockResolvedValue(undefined);

    render(
      <ChatInterface
        history={history}
        onSend={mockOnSend}
        loading={false}
      />
    );

    // 输入消息
    const input = screen.getByPlaceholderText('输入你的想法...') as HTMLInputElement;
    fireEvent.change(input, { target: { value: '测试消息' } });

    // 发送消息
    const sendButton = screen.getByText('发送');
    fireEvent.click(sendButton);

    // 等待并验证输入框被清空
    await waitFor(() => {
      expect(input.value).toBe('');
    });
  });

  it('应该支持多行输入', () => {
    const history: ReturnType<typeof createMockMessage>[] = [];

    render(
      <ChatInterface
        history={history}
        onSend={mockOnSend}
        loading={false}
      />
    );

    // 验证输入框是 textarea
    const input = screen.getByPlaceholderText('输入你的想法...');
    expect(input.tagName.toLowerCase()).toBe('textarea');
  });

  it('应该处理发送错误', async () => {
    const history: ReturnType<typeof createMockMessage>[] = [];
    mockOnSend.mockRejectedValue(new Error('发送失败'));

    render(
      <ChatInterface
        history={history}
        onSend={mockOnSend}
        loading={false}
      />
    );

    // 输入并发送消息
    const input = screen.getByPlaceholderText('输入你的想法...');
    fireEvent.change(input, { target: { value: '测试消息' } });

    const sendButton = screen.getByText('发送');
    fireEvent.click(sendButton);

    // 验证错误被处理（不抛出异常）
    await waitFor(() => {
      expect(mockOnSend).toHaveBeenCalled();
    });
  });
});
